/**
 * Id-based asset loader with procedural fallbacks.
 *
 * Every asset is requested by id (e.g. 'tex.carpet', 'mdl.tv_head'). If the runtime index
 * (generated by `npm run assets`) lists a converted file, it is loaded; otherwise — or if the
 * load fails — a procedural stand-in with the same id is generated. Code never references
 * file paths directly, so dropping in real files later needs no code changes.
 */
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import { Rng } from '../core/rng';
import { clonePsx, conformToPsx, psxMaterial, psxTexture, type PsxMaterial } from '../render/psxMaterial';
import index from './manifest.json';

type IndexEntry = { type: string; url: string };
const INDEX = (index as { assets: Record<string, IndexEntry> }).assets;

// ---------------------------------------------------------------------------------------
// Procedural textures (64×64 canvases)
// ---------------------------------------------------------------------------------------
type TexGen = (ctx: CanvasRenderingContext2D, s: number, r: Rng) => void;

const hex = (r: number, g: number, b: number) => `rgb(${r | 0},${g | 0},${b | 0})`;

function noise(ctx: CanvasRenderingContext2D, s: number, r: Rng, base: [number, number, number], amt: number): void {
  for (let y = 0; y < s; y++)
    for (let x = 0; x < s; x++) {
      const n = (r.float() - 0.5) * amt;
      ctx.fillStyle = hex(base[0] + n, base[1] + n * 0.8, base[2] + n * 0.6);
      ctx.fillRect(x, y, 1, 1);
    }
}

const TEX_GEN: Record<string, TexGen> = {
  'tex.wall_panel': (c, s, r) => {
    noise(c, s, r, [70, 42, 24], 18);
    for (let x = 0; x < s; x += 16) {
      c.fillStyle = 'rgba(20,10,5,0.8)';
      c.fillRect(x, 0, 2, s);
      c.fillStyle = 'rgba(120,80,45,0.35)';
      c.fillRect(x + 2, 0, 1, s);
    }
    for (let i = 0; i < 40; i++) {
      c.fillStyle = 'rgba(30,15,8,0.35)';
      c.fillRect(r.int(s), r.int(s), 1, 4 + r.int(10));
    }
  },
  'tex.carpet': (c, s, r) => {
    noise(c, s, r, [92, 20, 26], 30);
    for (let y = 0; y < s; y += 8)
      for (let x = (y / 8) % 2 ? 4 : 0; x < s; x += 8) {
        c.fillStyle = 'rgba(180,120,40,0.35)';
        c.fillRect(x + 2, y + 2, 3, 3);
      }
    for (let i = 0; i < 5; i++) {
      c.fillStyle = 'rgba(30,20,10,0.35)';
      c.beginPath();
      c.arc(r.int(s), r.int(s), 3 + r.int(7), 0, Math.PI * 2);
      c.fill();
    }
  },
  'tex.curtain': (c, s, r) => {
    for (let x = 0; x < s; x++) {
      const f = 0.55 + 0.45 * Math.sin((x / s) * Math.PI * 8);
      for (let y = 0; y < s; y++) {
        const n = (r.float() - 0.5) * 14;
        c.fillStyle = hex(110 * f + n, 18 * f, 28 * f);
        c.fillRect(x, y, 1, 1);
      }
    }
  },
  'tex.wallpaper': (c, s, r) => {
    noise(c, s, r, [92, 84, 58], 16);
    c.fillStyle = 'rgba(60,40,20,0.45)';
    for (let y = 0; y < s; y += 16)
      for (let x = (y / 16) % 2 ? 8 : 0; x < s; x += 16) {
        c.fillRect(x + 6, y + 2, 4, 12);
        c.fillRect(x + 2, y + 6, 12, 4);
      }
    for (let i = 0; i < 3; i++) {
      c.fillStyle = 'rgba(40,30,10,0.5)';
      c.fillRect(r.int(s), 0, 2 + r.int(4), s);
    }
  },
  'tex.metal': (c, s, r) => {
    noise(c, s, r, [92, 90, 86], 24);
    for (let i = 0; i < 30; i++) {
      c.fillStyle = `rgba(${120 + r.int(40)},${55 + r.int(20)},20,0.5)`;
      c.fillRect(r.int(s), r.int(s), 2 + r.int(6), 2 + r.int(6));
    }
  },
  'tex.leather': (c, s, r) => noise(c, s, r, [96, 26, 20], 22),
  'tex.stage_wood': (c, s, r) => {
    noise(c, s, r, [84, 56, 34], 16);
    for (let y = 0; y < s; y += 8) {
      c.fillStyle = 'rgba(25,14,6,0.8)';
      c.fillRect(0, y, s, 1);
    }
  },
  'tex.cabinet_wood': (c, s, r) => {
    noise(c, s, r, [110, 68, 36], 16);
    for (let y = 0; y < s; y += 3) {
      c.fillStyle = `rgba(60,30,10,${0.1 + r.float() * 0.2})`;
      c.fillRect(0, y, s, 1);
    }
  },
  'tex.plaster': (c, s, r) => {
    noise(c, s, r, [110, 104, 92], 22);
    for (let i = 0; i < 8; i++) {
      c.fillStyle = 'rgba(60,50,40,0.5)';
      c.fillRect(r.int(s), r.int(s), 4 + r.int(8), 2 + r.int(5));
    }
  },
};

function proceduralTexture(id: string): THREE.Texture {
  const s = 64;
  const cv = document.createElement('canvas');
  cv.width = cv.height = s;
  const ctx = cv.getContext('2d')!;
  const gen = TEX_GEN[id] ?? ((c: CanvasRenderingContext2D, sz: number, r: Rng) => noise(c, sz, r, [90, 80, 70], 20));
  gen(ctx, s, new Rng(id));
  return psxTexture(new THREE.CanvasTexture(cv));
}

// ---------------------------------------------------------------------------------------
// Procedural models (stand-ins with the same ids)
// ---------------------------------------------------------------------------------------
const MODEL_GEN: Record<string, () => THREE.Object3D> = {
  'mdl.tv_head': () => {
    const g = new THREE.Group();
    const body = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.42, 0.42), psxMaterial({ color: 0x5a4a38 }));
    g.add(body);
    const ant = new THREE.Mesh(new THREE.CylinderGeometry(0.008, 0.008, 0.3, 4), psxMaterial({ color: 0x888888 }));
    ant.position.set(0.08, 0.32, 0);
    ant.rotation.z = -0.4;
    g.add(ant);
    return g;
  },
  'mdl.bulb': () => new THREE.Mesh(new THREE.SphereGeometry(0.05, 6, 4), psxMaterial({ color: 0xfff0c0 })),
  'mdl.socket': () => new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.035, 0.08, 6), psxMaterial({ color: 0x2a2a2a })),
  'mdl.fluorescent': () => {
    const g = new THREE.Group();
    g.add(new THREE.Mesh(new THREE.BoxGeometry(1.2, 0.05, 0.12), psxMaterial({ color: 0x777770 })));
    const t = new THREE.Mesh(new THREE.CylinderGeometry(0.02, 0.02, 1.1, 5), psxMaterial({ color: 0xe8f0ff, lit: false }));
    t.rotation.z = Math.PI / 2;
    t.position.y = -0.04;
    g.add(t);
    return g;
  },
  'mdl.pocket_watch': () => {
    const m = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 0.015, 10), psxMaterial({ color: 0xc8b070 }));
    m.rotation.x = Math.PI / 2;
    return m;
  },
  'mdl.alarm_clock': () => {
    const g = new THREE.Group();
    const m = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, 0.04, 10), psxMaterial({ color: 0x9a3020 }));
    m.rotation.x = Math.PI / 2;
    g.add(m);
    return g;
  },
  'mdl.prize_cabinet': () => new THREE.Mesh(new THREE.BoxGeometry(1, 1.6, 0.5), psxMaterial({ color: 0x6a4020 })),
};

/**
 * Bake an imported scene into one mesh per texture (world transforms applied), so each
 * imported prop costs one draw call.
 */
function flattenModel(root: THREE.Object3D): THREE.Object3D {
  root.updateMatrixWorld(true);
  const byMap = new Map<THREE.Texture | null, { mat: PsxMaterial; geos: THREE.BufferGeometry[] }>();
  root.traverse((o) => {
    const m = o as THREE.Mesh;
    if (!m.isMesh) return;
    const mat = m.material as PsxMaterial;
    const key = mat.uniforms.map.value as THREE.Texture | null;
    let e = byMap.get(key);
    if (!e) {
      e = { mat, geos: [] };
      byMap.set(key, e);
    }
    let g = m.geometry.index ? m.geometry.toNonIndexed() : m.geometry.clone();
    g.applyMatrix4(m.matrixWorld);
    for (const name of Object.keys(g.attributes)) if (!['position', 'normal', 'uv'].includes(name)) g.deleteAttribute(name);
    const n = g.getAttribute('position').count;
    if (!g.getAttribute('normal')) g.computeVertexNormals();
    if (!g.getAttribute('uv')) g.setAttribute('uv', new THREE.BufferAttribute(new Float32Array(n * 2), 2));

    e.geos.push(g);
  });
  const out = new THREE.Group();
  for (const { mat, geos } of byMap.values()) {
    const merged = mergeGeometries(geos, false);
    if (merged) out.add(new THREE.Mesh(merged, mat));
  }
  return out;
}

// ---------------------------------------------------------------------------------------
// Loader
// ---------------------------------------------------------------------------------------
/** CSS font-family each font asset registers as. */
const FONT_FAMILIES: Record<string, string> = {
  'font.pixel': 'DeadAirPixel',
  'font.terminal': 'DeadAirTerminal',
  'font.title': 'DeadAirTitle',
  'font.body': 'DeadAirBody',
  'font.memo': 'DeadAirMemo',
};

export class Assets {
  private textures = new Map<string, THREE.Texture>();
  private models = new Map<string, THREE.Object3D>();
  private fonts = new Set<string>();
  readonly fallbacks: string[] = [];

  has(id: string): boolean {
    return !!INDEX[id];
  }

  ids(): string[] {
    return Object.keys(INDEX);
  }

  /** Load everything in the index; report progress 0..1 after each item. */
  async preload(onProgress: (p: number, id: string) => void): Promise<void> {
    const wanted = [...new Set([...Object.keys(TEX_GEN), ...Object.keys(MODEL_GEN), ...Object.keys(INDEX)])];
    let done = 0;
    const gltf = new GLTFLoader();
    const texLoader = new THREE.TextureLoader();
    await Promise.all(
      wanted.map(async (id) => {
        const e = INDEX[id];
        try {
          if (e?.type === 'texture') {
            const t = await texLoader.loadAsync(e.url);
            this.textures.set(id, psxTexture(t));
          } else if (e?.type === 'model') {
            const g = await gltf.loadAsync(e.url);
            conformToPsx(g.scene);
            this.models.set(id, flattenModel(g.scene));
          } else if (e?.type === 'font') {
            const name = FONT_FAMILIES[id] ?? 'DeadAirTerminal';
            const ff = new FontFace(name, `url(${e.url})`);
            await ff.load();
            document.fonts.add(ff);
            this.fonts.add(id);
          } else if (!e) {
            this.fallbacks.push(id);
          }
        } catch (err) {
          console.warn(`asset ${id} failed, using fallback`, err);
          this.fallbacks.push(id);
        }
        done++;
        onProgress(done / wanted.length, id);
      }),
    );
  }

  texture(id: string): THREE.Texture {
    let t = this.textures.get(id);
    if (!t) {
      t = proceduralTexture(id);
      this.textures.set(id, t);
    }
    return t;
  }

  /** A fresh clone of a model (materials cloned so they can be tinted independently). */
  model(id: string): THREE.Object3D {
    let m = this.models.get(id);
    if (!m) {
      const gen = MODEL_GEN[id];
      m = gen ? gen() : new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.1, 0.1), psxMaterial({ color: 0xff00ff }));
      this.models.set(id, m);
    }
    const c = m.clone(true);
    c.traverse((o) => {
      const mesh = o as THREE.Mesh;
      if (mesh.isMesh && mesh.material) mesh.material = clonePsx(mesh.material as PsxMaterial);
    });
    return c;
  }

  /** Scale a model so its largest dimension equals `size`, centred on its base. */
  fitted(id: string, size: number): THREE.Object3D {
    const m = this.model(id);
    const box = new THREE.Box3().setFromObject(m);
    const dim = box.getSize(new THREE.Vector3());
    const k = size / Math.max(dim.x, dim.y, dim.z, 1e-6);
    m.scale.multiplyScalar(k);
    const c = box.getCenter(new THREE.Vector3());
    m.position.set(-c.x * k, -box.min.y * k, -c.z * k);
    const g = new THREE.Group();
    g.add(m);
    return g;
  }

  fontLoaded(id: string): boolean {
    return this.fonts.has(id);
  }
}
